import { createRESTModule, toURLSearchParams } from './rest-modules.js';
/**
 * The single shared method factory: binds the per-method constants (verb +
 * proto path) and the service's url resolver as an SDK method. The raw JSON
 * response data is returned — no transformations.
 *
 * `postFallbackPath` is set only on GET methods whose service declares an
 * explicit POST mapping for the same RPC: the client switches to that POST
 * past 4000 chars of query string (the long-url fallback). GETs without a
 * declared POST route never fall back — a blind same-route POST could hit a
 * different RPC.
 * @param verb - The HTTP verb of the method's chosen mapping.
 * @param protoPath - The method's proto route template.
 * @param resolveServiceUrl - The generated resolver of the method's service.
 * @param postFallbackPath - The declared POST route for long GET urls, if any.
 * @returns The bound SDK method.
 */
export function restMethod(verb, protoPath, resolveServiceUrl, postFallbackPath) {
    // The descriptor must not dereference httpClient at construction time:
    // createClient probes modules by calling them with no arguments.
    const descriptor = (httpClient) => async (request) => {
        const { data } = await httpClient.request(({ host }) => buildRequestOptions(host, request ?? {}, verb, protoPath, resolveServiceUrl, postFallbackPath));
        return data;
    };
    return createRESTModule(descriptor);
}
/**
 * The one request-options builder that replaces every generated per-method
 * factory: GET/DELETE requests carry the payload as query params, everything
 * else sends it as the JSON body.
 * @param host - The API host the bound client resolved.
 * @param payload - The caller's request object.
 * @param verb - The HTTP verb of the method's chosen mapping.
 * @param protoPath - The method's proto route template.
 * @param resolveServiceUrl - The generated resolver of the method's service.
 * @param postFallbackPath - The declared POST route for long GET urls, if any.
 * @returns The request options for `httpClient.request`.
 */
function buildRequestOptions(host, payload, verb, protoPath, resolveServiceUrl, postFallbackPath) {
    const url = resolveServiceUrl({ protoPath, data: payload, host });
    if (verb === 'GET' || verb === 'DELETE') {
        return {
            method: verb,
            url,
            params: toURLSearchParams(payload, true),
            ...(postFallbackPath
                ? {
                    fallback: [
                        {
                            method: 'POST',
                            url: resolveServiceUrl({
                                protoPath: postFallbackPath,
                                data: payload,
                                host,
                            }),
                            data: payload,
                        },
                    ],
                }
                : {}),
        };
    }
    return { method: verb, url, data: payload };
}
